import os,sys,json,logging,importlib.util,threading,time
from pathlib import Path
RUN=Path(__file__).resolve().parent
PROJECT=Path(sys.argv[1]).resolve()
LABEL=sys.argv[2]
for key,p in {'SERENA_HOME':RUN/'serena-home','TEMP':RUN/'backend-temp','TMP':RUN/'backend-temp','npm_config_cache':RUN/'npm-cache','PYTHONPYCACHEPREFIX':RUN/'pycache'}.items():
 p.mkdir(parents=True,exist_ok=True);os.environ[key]=str(p)
os.environ['PYTHONDONTWRITEBYTECODE']='1'
import psutil
from serena.agent import SerenaAgent
from serena.config.context_mode import SerenaAgentContext
from serena.config.serena_config import ProjectConfig,RegisteredProject,SerenaConfig
from serena.repl.api.lsp_api import LspApi
from solidlsp.ls_config import LanguageServerId
logging.basicConfig(level=logging.INFO,stream=sys.stderr)
spec=importlib.util.spec_from_file_location('v5',RUN/'controls/scripts/serena-name-search-v5.py');mod=importlib.util.module_from_spec(spec);spec.loader.exec_module(mod)
agent=None;observed={};stop=threading.Event()
def watch():
 parent=psutil.Process(int(os.environ['EXPERIMENT_DRIVER_PID']))
 while not stop.is_set():
  try:
   for p in [parent]+parent.children(recursive=True):
    try:
     item={'pid':p.pid,'create_time':p.create_time(),'name':p.name()};observed[(p.pid,item['create_time'])]=item
    except psutil.NoSuchProcess:pass
  except psutil.NoSuchProcess:break
  stop.wait(.1)
thread=threading.Thread(target=watch,daemon=True);thread.start()
def send(x):print(json.dumps(x,ensure_ascii=False),flush=True)
def children():
 result=[]
 for p in psutil.Process().children(recursive=True):
  try:result.append({'pid':p.pid,'create_time':p.create_time(),'name':p.name()})
  except psutil.NoSuchProcess:pass
 return result
def overview(api,name):
 result=[];pending=list(reversed(api.get_symbols_overview(name).symbols))
 while pending:
  s=pending.pop();result.append({'id':s.get_name_path(),'line':s.line,'column':s.column,'kind':s.symbol_kind_name});pending.extend(reversed(list(s.iter_children())))
 return result
try:
 cfg=ProjectConfig(project_name='v5-'+LABEL,language_servers=[LanguageServerId.TYPESCRIPT],read_only=True)
 conf=SerenaConfig(projects=[RegisteredProject(str(PROJECT),cfg)],gui_log_window=False,web_dashboard=False,web_dashboard_open_on_launch=False,tool_timeout=90)
 agent=SerenaAgent(project=str(PROJECT),serena_config=conf,context=SerenaAgentContext.load('ide'));agent.execute_task(lambda:None,name='initialization',timeout=180)
 api=LspApi(agent);adapter=mod.SerenaNameSearchV5(api,PROJECT)
 send({'ready':True,'pid':os.getpid(),'create_time':psutil.Process().create_time(),'children':children(),'exposed_api':['find_names']})
 for line in sys.stdin:
  q=json.loads(line);start=time.perf_counter()
  try:
   if q['method']=='__audit_overview':callback=lambda:overview(api,q['args']['relative_path'])
   elif q['method']=='find_names':callback=lambda:adapter.find_names(**q['args'])
   else:raise ValueError('Unsupported backend operation')
   result=agent.execute_task(callback,name=q['method'],timeout=120);send({'id':q['id'],'result':result,'elapsed_ms':(time.perf_counter()-start)*1000})
  except Exception as e:send({'id':q['id'],'error':str(e),'elapsed_ms':(time.perf_counter()-start)*1000})
finally:
 before=children()
 if agent:agent.on_shutdown(timeout=8)
 remaining=[]
 for i in before:
  try:
   p=psutil.Process(i['pid'])
   if p.create_time()==i['create_time']:
    try:p.wait(timeout=5)
    except psutil.TimeoutExpired:remaining.append(i)
  except psutil.NoSuchProcess:pass
 stop.set();thread.join(timeout=2)
 (RUN/(LABEL+'-shutdown.json')).write_text(json.dumps({'children_before':before,'children_remaining':remaining,'on_shutdown':agent is not None,'observed_driver_tree':list(observed.values())},indent=2),encoding='utf8')

