const fs=require('node:fs'),path=require('node:path'),{createInterface}=require('node:readline');
class Peer{
 constructor(child,name,handler){this.child=child;this.name=name;this.handler=handler;this.next=0;this.pending=new Map();this.events=[];this.waiters=[];this.readyPromise=new Promise((r,j)=>{this.onReady=r;this.rejectReady=j});this.readyPromise.catch(()=>{});createInterface({input:child.stdout}).on('line',line=>this.line(line));child.stderr.on('data',x=>fs.appendFileSync(path.join(__dirname,'logs',name+'.stderr.log'),x));this.exit=new Promise((resolve,reject)=>{child.once('error',reject);child.once('exit',(code,signal)=>{this.exitCode=code;this.signal=signal;this.rejectReady(Error(name+'_exit_before_ready:'+code));for(const p of this.pending.values()){clearTimeout(p.timer);p.reject(Error(name+'_exit:'+code));}this.pending.clear();resolve({code,signal});});});}
 log(kind,value){fs.appendFileSync(path.join(__dirname,'logs',this.name+'.'+kind+'.jsonl'),JSON.stringify({at:Date.now(),value})+'\n');}
 line(line){let v;try{v=JSON.parse(line)}catch{return;}this.log('events',v);if(v.ready){this.onReady(v);return;}if(v.id!==undefined&&v.method){Promise.resolve(this.handler(v)).then(result=>this.child.stdin.write(JSON.stringify({id:v.id,result})+'\n')).catch(e=>this.child.stdin.write(JSON.stringify({id:v.id,error:{code:-32603,message:e.message}})+'\n'));}else if(v.id!==undefined){const p=this.pending.get(v.id);if(p){clearTimeout(p.timer);this.pending.delete(v.id);v.error?p.reject(Error(typeof v.error==='string'?v.error:JSON.stringify(v.error))):p.resolve(v.result??v);}}else{this.events.push(v);for(const w of [...this.waiters])if(w.test(v)){clearTimeout(w.timer);this.waiters.splice(this.waiters.indexOf(w),1);w.resolve(v);}}}
 request(method,params){return new Promise((resolve,reject)=>{const id=++this.next,timer=setTimeout(()=>{this.pending.delete(id);reject(Error(this.name+'_timeout:'+method))},method==='initialize'?600000:180000);this.pending.set(id,{resolve,reject,timer});this.log('requests',{id,method});this.child.stdin.write(JSON.stringify(this.name.startsWith('backend')?{id,method,args:params}:{id,method,params})+'\n');});}
 wait(test){const v=this.events.find(test);if(v)return Promise.resolve(v);return new Promise((resolve,reject)=>{const w={test,resolve,timer:setTimeout(()=>reject(Error(this.name+'_event_timeout')),600000)};this.waiters.push(w);});}
 async close(){for(const p of this.pending.values())clearTimeout(p.timer);for(const w of this.waiters)clearTimeout(w.timer);this.child.stdin.end();return this.exit;}
}
module.exports={Peer};

