 assert.equal(sourceCheck().changed.length,0);state.app_preflight={...read(path.join(run,'app-native-preflight.json')),reused_from_native_preflight:true,performed_in_current_attempt:false,current_backend_queried_before_performance:false};assert.equal(state.app_preflight.status,'PASS');save('app-native-preflight-reuse.json',state.app_preflight);
