 peer=new Peer(engine,'engine',async request=>{if(request.method!=='item/tool/call')throw Error('unexpected server request:'+request.method);const p=request.params,tool=p.tool??p.name;assert.equal(tool,'find_names');let a=p.arguments;if(typeof a==='string')a=JSON.parse(a);const start=Date.now();try{const result=await bpeer.request(tool,a);const text=JSON.stringify(result);log('dynamic-calls.jsonl',{tool,args:a,result,chars:text.length,elapsed_ms:Date.now()-start});return {success:true,contentItems:[{type:'inputText',text}]};}catch(e){log('dynamic-calls.jsonl',{tool,args:a,error:e.message,elapsed_ms:Date.now()-start});return {success:false,contentItems:[{type:'inputText',text:e.message}]};}});
