 if(!state.account.kmw_active){const matches=(accountState.profiles||[]).filter(p=>JSON.stringify(p).toLowerCase().includes('kmw'));assert.equal(matches.length,1,'Unique saved kmw profile required');const chosen=matches[0];const changed=await peer.request('azrael/account',{action:'switch',profileId:chosen.id});accountState=changed.state;state.account.normal_reselection=true;if(accountState.isSwitching){const ready=await peer.wait(v=>v.method==='azrael/account/updated'&&v.params?.activeProfileId===chosen.id&&!v.params?.isSwitching);accountState=ready.params;}state.account.kmw_active=accountState.activeProfileId===chosen.id;if(!state.account.kmw_active)throw Error('Normal kmw recovery not ready: '+(accountState.lastError||changed.error||'account unavailable'));}
