 const prompt=read(path.join(run,'prompt.json')),tools=read(path.join(run,'tool-contract.json'));assert.equal(tools.length,1);assert.equal(tools[0].name,'find_names');const t=await peer.request('thread/start',{model:state.model,modelProvider:state.provider,cwd:project,approvalPolicy:'never',sandbox:'danger-full-access',ephemeral:true,experimentalRawEvents:true,dynamicTools:tools,developerInstructions:prompt.developer});state.thread_id=t.thread.id;state.thread_start={model:t.model,modelProvider:t.modelProvider,effort:t.reasoningEffort??t.effort,instructionSources:t.instructionSources};
 state.source_before=sourceCheck();assert.equal(state.source_before.changed.length,0);const paths=['backend.py','native-peer.cjs','trial-driver.cjs','prompt.json','tool-contract.json',...dependencies.map(f=>'controls/'+f.relative_path)];state.control_manifest=paths.map(relative_path=>({relative_path,sha256:hash(path.join(run,relative_path))}));state.prompt_sha256=hash(path.join(run,'prompt.json'));state.tool_contract_sha256=hash(path.join(run,'tool-contract.json'));state.source_manifest_sha256=hash(path.join(run,'source-manifest.json'));state.start_file=path.join(run,'start-turn.json');state.status='PARTIAL_READY no model START issued';save('trial-readiness.json',state);console.log(JSON.stringify({status:state.status,thread:state.thread_id,engine:engine.pid,backend:state.backend_readiness.pid}));
 const decision=await new Promise((resolve,reject)=>{const check=()=>{if(!fs.existsSync(state.start_file))return;try{const x=read(state.start_file);clearInterval(timer);resolve(x);}catch(e){clearInterval(timer);reject(e)}};const timer=setInterval(check,250);check();});assert.equal(decision.approved,true);assert.equal(decision.lane,state.lane);state.source_at_start=sourceCheck();assert.equal(state.source_at_start.changed.length,0);for(const f of state.control_manifest)assert.equal(hash(path.join(run,f.relative_path)),f.sha256,'control changed:'+f.relative_path);
 state.performance_turn_count=1;state.start_epoch_ms=Date.now();const turn=await peer.request('turn/start',{threadId:state.thread_id,input:[{type:'text',text:prompt.user}],effort:'medium',summary:'none'});state.turn_id=turn.turn.id;const done=await peer.wait(v=>v.method==='turn/completed'&&v.params?.threadId===state.thread_id&&v.params?.turn?.id===state.turn_id);state.turn=done.params.turn;state.end_epoch_ms=Date.now();state.duration_ms=state.end_epoch_ms-state.start_epoch_ms;state.source_after=sourceCheck();state.status='TURN_TERMINAL';save('trial-terminal.json',state);console.log(JSON.stringify({status:state.status,turn_status:state.turn.status,duration_ms:state.duration_ms}));
}
main().catch(e=>{state.error=e.message;state.status='FAILED';process.exitCode=1;console.error(e.stack);}).finally(async()=>{if(peer){const e=await peer.close();state.actual_engine_exit=e.code;state.engine_signal=e.signal;}if(bpeer){const e=await bpeer.close();state.actual_backend_exit=e.code;state.backend_signal=e.signal;}save('driver-shutdown.json',state);console.log(JSON.stringify({status:'DRIVER_EXIT',engine:state.actual_engine_exit,backend:state.actual_backend_exit,performance_turns:state.performance_turn_count}));});

